&lt;h3 data-path-to-node=&quot;12&quot;&gt;&lt;strong data-path-to-node=&quot;12&quot; data-index-in-node=&quot;0&quot;&gt;TES COMPÉTENCES TECHNIQUES&lt;/strong&gt;&lt;/h3&gt;
